// Dedupe against static data so we only act on truly new posts.
// First run sees them all as 'new' — pre-seed if you want to skip backlog.
const seen = $workflow.staticData.global.seenGuids ??= [];
const newItems = $input.all().filter((item) => !seen.includes(item.json.guid));

// Mark them as seen so we don't fire again next cycle
for (const item of newItems) {
  if (!seen.includes(item.json.guid)) seen.push(item.json.guid);
}
// Keep the seen list bounded (last 200) so it doesn't grow forever
if (seen.length > 200) seen.splice(0, seen.length - 200);

return newItems;
